const test = require("node:test");
const assert = require("node:assert/strict");
const app = require("../app.js");

test("loadData returns the fallback when nothing is saved", () => {
  assert.deepEqual(app.loadData([]), []);
});

test("validateInputs checks bill, people, then tip", () => {
  assert.equal(app.validateInputs(0, 18, 2).valid, false);
  assert.equal(app.validateInputs(50, 18, 1.5).message, "Please enter at least 1 person.");
  assert.equal(app.validateInputs(50, -1, 2).message, "Tip percentage can't be negative.");
  assert.deepEqual(app.validateInputs(50, 18, 2), { valid: true, message: "" });
});

test("calculateSplit exact mode", () => {
  assert.deepEqual(app.calculateSplit(100, 15, 3, false), { tip: 15, total: 115, perPerson: 38.33 });
});

test("calculateSplit round-up mode", () => {
  assert.deepEqual(app.calculateSplit(100, 15, 3, true), { tip: 15, total: 117, perPerson: 39 });
});

