// Connects the page (index.html) to the logic in app.js.
(function () {
  var app = document.getElementById('app');
  var form = document.createElement('div');
  form.className = 'card';
  form.innerHTML =
    '<label for="bill-input">Bill amount ($)</label>' +
    '<input id="bill-input" type="number" step="0.01" min="0" inputmode="decimal" />' +
    '<label for="tip-input">Tip percentage (%)</label>' +
    '<input id="tip-input" type="number" step="1" min="0" inputmode="decimal" />' +
    '<div class="presets">' +
    '<button type="button" id="tip-preset-15">15%</button>' +
    '<button type="button" id="tip-preset-18">18%</button>' +
    '<button type="button" id="tip-preset-20">20%</button>' +
    '</div>' +
    '<label for="people-input">Number of people</label>' +
    '<input id="people-input" type="number" step="1" min="1" inputmode="numeric" />' +
    '<label class="check" for="round-up-checkbox">' +
    '<input id="round-up-checkbox" type="checkbox" />' +
    '<span>Round each share up to the next whole dollar</span></label>';
  app.appendChild(form);

  var message = document.createElement('p');
  message.id = 'message';
  message.setAttribute('aria-live', 'polite');
  app.appendChild(message);

  var results = document.createElement('div');
  results.id = 'results';
  results.hidden = true;
  results.innerHTML =
    '<p>Tip amount: <span id="tip-amount"></span></p>' +
    '<p>Grand total: <span id="grand-total"></span></p>' +
    '<p class="big">Each person pays: <span id="per-person"></span></p>';
  app.appendChild(results);

  var bill = document.getElementById('bill-input');
  var tip = document.getElementById('tip-input');
  var people = document.getElementById('people-input');
  var roundUp = document.getElementById('round-up-checkbox');

  var saved = null;
  try { saved = loadData(); } catch (e) { saved = null; }
  saved = saved || {};
  tip.value = typeof saved.tipPercent === 'number' ? saved.tipPercent : 18;
  people.value = typeof saved.people === 'number' ? saved.people : 2;
  roundUp.checked = saved.roundUp === true;

  function money(n) { return '$' + n.toFixed(2); }

  function highlightPreset() {
    [15, 18, 20].forEach(function (p) {
      var b = document.getElementById('tip-preset-' + p);
      b.classList.toggle('active', Number(tip.value) === p && tip.value !== '');
    });
  }

  function update() {
    highlightPreset();
    if (bill.value === '') {
      message.textContent = 'Enter a bill amount to see the tip and each share.';
      message.className = 'hint';
      results.hidden = true;
      return;
    }
    var b = Number(bill.value);
    var t = Number(tip.value);
    var n = Number(people.value);
    var v = validateInputs(b, t, n);
    if (!v.valid) {
      message.textContent = v.message;
      message.className = '';
      results.hidden = true;
      return;
    }
    message.textContent = '';
    message.className = '';
    results.hidden = false;
    var r = calculateSplit(b, t, n, roundUp.checked);
    document.getElementById('tip-amount').textContent = money(r.tip);
    document.getElementById('grand-total').textContent = money(r.total);
    document.getElementById('per-person').textContent = money(r.perPerson);
  }

  function save() {
    saveData({
      tipPercent: Number(tip.value),
      people: Number(people.value),
      roundUp: roundUp.checked
    });
  }

  function onChange() { save(); update(); }

  [bill, tip, people].forEach(function (el) { el.addEventListener('input', onChange); });
  roundUp.addEventListener('change', onChange);
  [15, 18, 20].forEach(function (p) {
    document.getElementById('tip-preset-' + p).addEventListener('click', function () {
      tip.value = p;
      onChange();
    });
  });

  update();
})();
